"""Summarize workflow tables without changing the node."""
import argparse
from datetime import datetime, timedelta, timezone
import json
from pathlib import Path
import re

EVERY = re.compile(r"[1-9][0-9]*[rsmhd]")
CODE = re.compile(r"[+-]?[0-9]+")
SECONDS = {"s": 1, "m": 60, "h": 3600, "d": 86400}
REQUIRED = {"routines": ("name", "every", "last_time", "last_code"),
            "schedule": ("name", "at", "claimed")}
STATES = {"routines": ("running", "never", "failed", "overdue", "ok"),
          "schedule": ("interrupted", "due", "pending")}


def reject_constant(value):
    raise ValueError(value)


def read_table(node, name, bad):
    try:
        with (node / "wf" / (name + ".json")).open(encoding="utf-8") as stream:
            value = json.load(stream, parse_constant=reject_constant)
    except FileNotFoundError:
        return []
    except (OSError, UnicodeError, ValueError):
        bad.append({"table": name, "row": None, "why": "bad_table"})
        return []
    if (not isinstance(value, dict) or value.get("contract") != "wf-table/1"
            or not isinstance(value.get("columns"), list)
            or not all(isinstance(col, str) for col in value["columns"])
            or not isinstance(value.get("rows"), list)):
        bad.append({"table": name, "row": None, "why": "bad_table"})
        return []
    return value["rows"]


def stamp(value, now):
    result = datetime.fromisoformat(value)
    return result.replace(tzinfo=now.tzinfo) if result.tzinfo is None else result


def valid_fields(row, name):
    return (isinstance(row, dict)
            and all(isinstance(value, str) for value in row.values())
            and all(key in row for key in REQUIRED[name])
            and bool(row["name"]))


def routine(row, now):
    if not valid_fields(row, "routines") or not EVERY.fullmatch(row["every"]):
        raise ValueError("invalid routine")
    last = stamp(row["last_time"], now) if row["last_time"] else None
    text = row["last_code"]
    if text == "":
        code = None
    elif text == "running":
        code = text
    elif CODE.fullmatch(text):
        code = int(text)
    else:
        raise ValueError("invalid code")
    suffix = row["every"][-1]
    following = (last + timedelta(seconds=int(row["every"][:-1]) * SECONDS[suffix])
                 if last is not None and suffix != "r" else None)
    next_time = (following.astimezone(timezone.utc).isoformat(timespec="seconds").replace("+00:00", "Z")
                 if following is not None else None)
    if code == "running":
        state = "running"
    elif last is None:
        state = "never"
    elif isinstance(code, int) and code != 0:
        state = "failed"
    elif following is not None and now >= following:
        state = "overdue"
    else:
        state = "ok"
    return {"name": row["name"], "every": row["every"],
            "last_time": row["last_time"] or None, "last_code": code,
            "state": state, "next": next_time}


def schedule(row, now):
    if not valid_fields(row, "schedule"):
        raise ValueError("invalid schedule")
    at = stamp(row["at"], now)
    state = "interrupted" if row["claimed"] else "due" if at <= now else "pending"
    return {"name": row["name"], "at": row["at"], "state": state}


def summarize(node, now):
    bad = []
    output = {"v": 1, "routines": [], "schedule": [],
              "counts": {name: {state: 0 for state in STATES[name]} for name in STATES},
              "bad": bad}
    for table, convert in (("routines", routine), ("schedule", schedule)):
        seen = set()
        for index, row in enumerate(read_table(node, table, bad)):
            name = row.get("name") if isinstance(row, dict) else None
            if isinstance(name, str) and name:
                if name in seen:
                    bad.append({"table": table, "row": index, "why": "dup_name"})
                    continue
                seen.add(name)
            try:
                item = convert(row, now)
            except (ValueError, OverflowError, TypeError):
                bad.append({"table": table, "row": index, "why": "bad_row"})
                continue
            output[table].append(item)
            output["counts"][table][item["state"]] += 1
        output[table].sort(key=lambda item: item["name"])
    bad.sort(key=lambda item: (item["table"], -1 if item["row"] is None else item["row"], item["why"]))
    return output


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only workflow runs summary")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("invalid --now")
    if now.tzinfo is None:
        parser.error("--now requires a timezone")
    if not args.folder.is_dir():
        parser.error("folder is not a directory")
    print(json.dumps(summarize(args.folder, now), ensure_ascii=True, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
